import{_ as s,c as t,o as r,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"爻变第十四","description":"杭氏易学 - 爻变第十四","frontmatter":{"title":"爻变第十四","description":"杭氏易学 - 爻变第十四"},"headers":[],"relativePath":"zh/classics/hangshi/015.md","filePath":"zh/classics/hangshi/015.md"}'),i={name:"zh/classics/hangshi/015.md"};function c(o,a,l,d,h,p){return r(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"爻变第十四",tabindex:"-1"},[n("爻变第十四 "),e("a",{class:"header-anchor",href:"#爻变第十四","aria-label":"Permalink to “爻变第十四”"},"​")],-1),e("p",null,"先儒言卦变者多矣。虞氏以后，众说纷纭，莫衷一是。虞《易》既无完书，其注及《周易集林》，仅于《李氏集解》中得一鳞片甲，语焉不详。汉上朱氏，据此以定虞氏卦变图，当时已多异议。李氏挺之，有六十四相生及反对两图。朱子《本义》，复有变更。阴阳重出，其为卦乃至一百二十有四。虽称根据《彖传》，而其举例之十九卦，有自一卦来，两卦三卦来者，参差不一，亦不能自圆其说。后之为图者更多，如朱枫林等，更自郐以下无足言矣。虞李二氏之图，皆根本乾坤，其立论自不可磨。后儒如来氏知德，胡氏沧晓，钱氏辛楣，焦氏理堂，各有变通修正，均不能越其范围。然皆爻变，而不尽为卦变也。夫卦者，必一卦尽变，如坤之变乾，巽之变震，斯谓之卦变可矣。若乾变姤夬同人大有小畜履，坤变剥复师比谦豫，则只一爻变。上下之乾坤，固未变焉。且占变知来，因贰以济民行，事物万变，乌能以六十四卦之变，应之而不穷乎？故朱子占法，据《左》《国》所载故事为例，而又自定前十卦后十卦之别，以补其未备。无论其所谓前后十卦者，即其卦变图百二十四卦之次序，决非古人所有。即能相合，而上下二编彖辞象辞并计，亦只四百四十八变，再加合两卦彖辞，亦仅五百十二，乌能悉应所占之事，而定其吉凶？其无当可断言也。《周官》太卜所掌三《易》，自别有占法。而文周上下二编之《彖》、《象》，特其纲领。孔子《十翼》，但示人以观象玩辞，为进德明道之本，来尝为人言占卜之方也。“大衍”一章，明象数之根本。揲蓍求卦，以尽变通之义。引伸触类，以尽天下之能事。亦非专为卜筮而言也。自“挂一”，“再扐”之义不明，自唐以后，异说纷起。如刘梦得、张辕、庄绰、程伊川、朱元晦、张理、郭兼山诸家，议论不一。要皆书生之见，无当于事，无与于《易》。故历代精于占筮者，皆屏不用，徒留为经生家聚讼之资而已 【沈氏需时眇言，据天地之数由大衍求一之术，证以微积分，合而定揲四之义，与《易》象数皆能确合。俟参考仪象诸书，更试验得实，当别为一书详之。】 。故兹编于卦变之说，概弃不录。卦变皆由爻变，言爻变即所以言卦变也。卦变可图，爻变则非图所能尽也。略图示意，阅者以意会之可耳。",-1),e("p",null,"爻分阴阳奇偶二者而已。卦有六爻，乾坤十有二爻而已。一爻变至二三四五六爻俱变，一卦之变，六十有四，四千零九十六而已。四千九十六，亦乌足尽万事万物之变哉！故爻之变，有时有位，有主有应，有物有事，而数与象，犹不预焉。如同一卦也，卦不变，爻亦不变。而时与位六者有一变，则利害情伪，已迥乎不同，此不变之变一也。更有爻不变而象数已变者，如七与九，皆阳也。六与八，皆阴也。七八易九六，爻之阴阳如故，而数与象，均各不同。此不变之变二也。故《易》曰：动则变，变则通。动之机甚多，不必爻之动而卦始变也。朱子曰：“坤初之变为复，非顿然而变也。自小雪起，一日变一分，至冬至而始成复之一爻。”知言哉！惟其变由微而显，由显而著，至见于象，而阴阳始判，吉凶始见耳。仅知卦爻之变，而不知不变之变，不足以言卦，不足以言爻，并不足以言变也。上图略举其例，非事物之必初上，主应之必二五。六爻皆具此六者，而六者又各有变化之不同。如今昔时也，盛衰亦时也，月建日符亦时也。位则有方位，有地位，有贵贱之位。千态万状，何可数限？但概之以动，察之以几，知几其神，而《易》始可言矣。",-1)])])}const f=s(i,[["render",c]]);export{_ as __pageData,f as default};
